// CHEMISTRY — 16 concepts
// ─────────────────────────────────────────────────────────────────────────────
const CHEMISTRY: Row[] = [
  ["atoms-elements", 0, "Atoms & elements", "The building blocks of matter.", "An element is one type of atom, listed in the periodic table — 118 known. Atoms: protons (+, in nucleus), neutrons (0), electrons (−, in shells). Atomic number = protons = the element's identity. Chemical reactions rearrange atoms but never change them — matter is conserved.", [], []],
  ["compounds-mixtures", 1, "Compounds & mixtures", "Chemically bonded vs physically mixed.", "Compounds bond elements chemically in fixed ratios — water is always H₂O. Mixtures just sit together — air, sea water, alloys — separable by physical means: filtration, distillation, chromatography. The difference drives everything from ore processing to drug purification.", ["atoms-elements"], []],
  ["periodic-table", 1, "The periodic table", "Elements ordered by atomic number into repeating patterns.", "Rows (periods) fill electron shells; columns (groups) share outer electrons and thus chemistry. Group 1 metals react fiercely with water; group 7 halogens grab electrons; group 8 noble gases react with almost nothing. Trends run both ways: down a group atoms grow and react differently; across a period metallic character fades.", ["atoms-elements", "electron-shells"], ["group-trend"]],
  ["electron-shells", 1, "Electron configuration", "How electrons fill shells — 2, 8, 8.", "Electrons occupy shells: 2 in the first, 8 in the second, 8 in the third (for GCSE). Sodium (11 electrons): 2, 8, 1 — that lonely outer electron explains its reactivity. Full outer shells are stable; everyone else borrows, lends or shares to get there. Configuration is the grammar of bonding.", ["atoms-elements"], []],
  ["ionic-bonding", 2, "Ionic bonding", "Electron transfer between metal and non-metal.", "Metals lose electrons to become positive ions; non-metals gain to become negative. Na gives Cl one electron: Na⁺ + Cl⁻ attract into a giant lattice — high melting points, conductive when molten or dissolved. The formula comes from charge balance: Al³⁺ + O²⁻ needs Al₂O₃. Giant structure means strong electrostatics throughout.", ["electron-shells"], []],
  ["covalent-bonding", 2, "Covalent bonding", "Shared electron pairs between non-metals.", "Non-metals share pairs to complete shells: H₂O, CH₄, O₂ (double bond). Simple molecules: strong bonds inside, weak forces between — hence low boiling points, no conductivity. Giant covalent exceptions: diamond (hard, 3-D network), graphite (layers that slide, conducts — the pencil and the electrode).", ["electron-shells"], []],
  ["metallic-bonding", 2, "Metals & alloys", "Positive ions in a sea of delocalised electrons.", "Metal atoms pack as cations in a mobile 'sea' of shared electrons. That sea conducts electricity and heat, and lets layers slide — malleable, ductile. Alloys mix atom sizes to jam the slide: stronger than pure metals. Stainless steel, bronze, solder — engineered crystals.", ["ionic-bonding"], []],
  ["moles-calcs", 2, "The mole & calculations", "Counting particles by mass: Avogadro's number.", "One mole = 6.02 × 10²³ particles = the relative formula mass in grams. Moles = mass ÷ Mr. Concentration = moles ÷ volume. Balanced equations give ratios: 2H₂ + O₂ → 2H₂O means hydrogen : oxygen : water = 2 : 1 : 2. Limiting reagent: the reactant that runs out first caps the product.", ["compounds-mixtures", "proportion"], ["mr-mass"]],
  ["equations-stoich", 2, "Chemical equations", "Symbol equations, balanced, with state symbols.", "Equations must balance — atoms are conserved: CH₄ + 2O₂ → CO₂ + 2H₂O (4 H, 1 C, 4 O each side). State symbols (s), (l), (g), (aq) add physical meaning. Ionic equations strip spectators to the chemistry that actually happens. Balancing is algebra with atoms.", ["atoms-elements", "linear-equations"], ["mass-balance"]],
  ["rates-reaction", 2, "Rates of reaction", "How fast reactants become products, and how to change it.", "Rate = change ÷ time. Four levers: temperature (particles faster, more energetic collisions), concentration/pressure (more particles per volume), surface area (more exposed surface), catalysts (lower the energy barrier, unchanged at the end). Collision theory explains all four: rate = collision frequency × success fraction.", ["energy-conservation"], []],
  ["energy-changes", 3, "Energy changes & bonding", "Exothermic vs endothermic; bond energy accounting.", "Breaking bonds absorbs energy; making bonds releases it. Exothermic: more released than absorbed — heat given out (combustion, neutralisation). Endothermic: the reverse (photosynthesis, sherbet). Reaction profiles show the energy hill and the activation energy — the barrier catalysts lower.", ["rates-reaction", "energy-conservation"], []],
  ["acids-bases", 2, "Acids, bases & salts", "H⁺ donors, OH⁻ acceptors, and neutralisation.", "Acids release H⁺ (pH < 7); alkalis release OH⁻ (pH > 7); neutralisation: acid + base → salt + water. HCl → chloride salts, H₂SO₄ → sulfates, HNO₃ → nitrates. Titrations measure exact concentrations. Strong vs concentrated: full ionisation vs amount per litre — different axes entirely.", ["compounds-mixtures", "ionic-bonding"], ["strong-conc"]],
  ["electrolysis", 3, "Electrolysis", "Electricity splitting ionic compounds.", "Molten or dissolved ions move to electrodes: positive cations to the cathode (−, gain electrons), negative anions to the anode (+, lose electrons). Electrolysis of brine makes chlorine, hydrogen and sodium hydroxide; of aluminium oxide, the metal itself. Half-equations bookkeep the electrons.", ["ionic-bonding", "electricity-circuits"], []],
  ["organic-intro", 3, "Organic chemistry", "Carbon compounds: crude oil to polymers.", "Carbon chains make millions of compounds. Alkanes are saturated (CₙH₂ₙ₊₂); alkenes have a reactive C=C double bond. Crude oil separates by distillation into fractions; cracking splits big alkanes into small alkenes (feedstock for plastics). Combustion releases energy; incomplete combustion makes deadly CO.", ["covalent-bonding"], []],
  ["equilibria", 4, "Reversible reactions & equilibrium", "Reactions that run both ways, and where they settle.", "Many reactions run both ways: N₂ + 3H₂ ⇌ 2NH₃. Le Chatelier: push the conditions, the equilibrium shifts to oppose the change — more pressure shifts toward fewer gas molecules, more heat toward the endothermic direction. The Haber process balances yield against rate and cost: 450 °C, 200 atm, iron catalyst.", ["rates-reaction", "energy-changes"], []],
  ["analysis-tests", 3, "Chemical analysis", "Tests that identify ions and gases.", "Flame tests and sodium hydroxide precipitates identify metal ions (Cu²⁺ blue, Fe³⁺ brown). Gases: hydrogen squeaky pop with a lit splint, oxygen relights a glowing splint, CO₂ turns limewater cloudy, chlorine bleaches damp litmus. Instrumental methods (mass spec, chromatography) go further: sensitivity, speed, accuracy.", ["atoms-elements", "compounds-mixtures"], []],
];

