const COMPUTING: Row[] = [
  ["what-is-code", 0, "What is code?", "Instructions a computer executes, written precisely.", "Code is a set of unambiguous instructions: computers do exactly what you say, not what you mean. Programs are written in languages (Python, JavaScript) that translate to machine operations. The core skill is decomposition: breaking 'make a game' into 'draw a paddle, move it, bounce a ball'. Precision is the discipline; creativity is the reward.", [], []],
  ["variables", 0, "Variables & types", "Named boxes holding values: numbers, strings, booleans.", "A variable names a value: score = 0. Types matter: integers (3), floats (3.14), strings ('hello'), booleans (true/false). Assignment stores; expressions compute: score = score + 10. Casting converts: int('42') gives the number. Naming well is half of readable code.", ["what-is-code"], []],
  ["conditionals", 0, "Conditionals", "Decisions: if, else if, else.", "Branching makes programs respond: if temperature > 30 → 'hot', elif > 20 → 'warm', else → 'cool'. Conditions are boolean expressions: ==, !=, <, >, and/or/not. Nesting handles compound logic, but flat conditions with early returns usually read better. Every app you use is mostly conditionals.", ["variables"], []],
  ["loops", 0, "Loops", "Repetition: for (known count), while (known condition).", "for loops repeat a known number of times (each item in a list); while loops repeat until a condition changes — beware infinite loops. Loop + list is the workhorse of data processing: total = 0; for x in prices: total += x. Off-by-one errors are the classic bug: does the range include the end?", ["variables"], []],
  ["lists-arrays", 1, "Lists & arrays", "Ordered collections with index access.", "A list holds many values in order: fruits[0] is the first. Append adds, remove deletes, len measures. Iteration visits each: for fruit in fruits. Lists nest: a grid is a list of lists — the foundation of images, boards, spreadsheets. Choosing the right structure (list, set, dictionary) is half the design.", ["variables", "loops"], []],
  ["functions-code", 1, "Functions & decomposition", "Reusable named blocks with inputs and outputs.", "def greet(name): return 'Hello, ' + name — define once, call many. Parameters take input; return gives output. Decomposition: big problems split into small named functions you can test separately. DRY — don't repeat yourself — copies are bugs waiting to diverge.", ["variables", "conditionals"], []],
  ["dictionaries", 1, "Dictionaries & hashing", "Key–value lookup in constant time.", "A dictionary maps keys to values: ages['Amina'] = 14 — instant lookup regardless of size, via hashing. Perfect for counting (tally of letters), indexing (name → record), caching (computed → saved). Sets hold unique items with fast membership. Choosing between list, dict and set changes performance by orders of magnitude.", ["lists-arrays"], []],
  ["algorithms-search", 2, "Searching algorithms", "Linear vs binary: scan or halve.", "Linear search checks each item — works on anything, slow on big data. Binary search halves the candidates each step — 1,000,000 items found in ~20 steps — but needs sorted data. The lesson: algorithm choice can beat any amount of hardware speed. Sorting first is often worth it.", ["lists-arrays", "conditionals"], []],
  ["algorithms-sort", 2, "Sorting algorithms", "Bubble, merge, and the cost of ordering.", "Bubble sort swaps neighbours — simple, O(n²), fine for tiny inputs. Merge sort splits, sorts halves, merges — O(n log n), scales to millions. Watching 30 bubbles vs 30 merges makes the difference visceral. Big-O notation measures growth: the shape of the cost curve, not the milliseconds.", ["algorithms-search"], []],
  ["recursion", 3, "Recursion", "Functions that call themselves, with a base case.", "A recursive function solves a problem by solving smaller versions of itself: factorial(n) = n × factorial(n−1), stopping at factorial(0) = 1. The base case stops infinite descent; the call stack remembers where to return. Trees, mazes and divide-and-conquer algorithms are natural recursions.", ["functions-code"], []],
  ["complexity", 3, "Computational thinking & Big-O", "Abstraction, decomposition, and growth rates.", "Computational thinking: decompose the problem, abstract away detail, recognise patterns, design an algorithm. Big-O classes: O(1) instant, O(log n) halving, O(n) a pass, O(n log n) good sorting, O(n²) pairwise, O(2ⁿ) intractable. The difference between 2ⁿ and n log n at n = 100 is the difference between impossible and instant.", ["algorithms-sort", "functions-code"], []],
  ["binary-data", 1, "Binary & data representation", "Everything is bits: numbers, text, images, sound.", "Computers store everything in binary. 8 bits = 1 byte = 256 values. Text maps numbers to letters (ASCII, Unicode — emoji included). Images are pixel grids: RGB triples; more bits, more colours. Sound samples amplitude thousands of times per second. Compression removes redundancy: lossless (ZIP) vs lossy (JPEG, MP3).", ["number-bases"], []],
  ["networks", 2, "Networks & the internet", "Packets, protocols, and the web's stack.", "The internet moves packets: data chopped, addressed (IP), routed hop by hop, reassembled (TCP guarantees order). DNS turns names into addresses. HTTP/HTTPS request web pages; latency and bandwidth set the experience. Client and server split the work — your browser asks, servers answer.", ["binary-data"], []],
  ["cybersecurity", 2, "Cybersecurity", "Threats and defences: hashing, encryption, common sense.", "Threats: phishing (trick the human), malware (poison the machine), brute force (guess passwords). Defences: strong unique passwords, 2FA, encryption (scramble without the key), hashing (one-way fingerprint for stored passwords), updates (patch the holes). Security is a systems property — the weakest link is usually a person, not a cipher.", ["networks", "logic-maths"], []],
  ["databases-sql", 3, "Databases", "Structured storage and queries.", "Relational databases store tables; SQL selects: SELECT name FROM students WHERE grade > 80. Primary keys identify rows; foreign keys link tables. Normalisation removes duplication. Indexes trade write speed for read speed. Nearly every app you use is a database with a user interface on top.", ["dictionaries"], []],
  ["web-stack", 2, "How the web works", "HTML structure, CSS style, JavaScript behaviour.", "HTML gives structure (headings, paragraphs, links), CSS gives style (colours, layout, animation), JavaScript gives behaviour (respond to clicks, fetch data). The DOM is the live tree the browser manipulates. Front-end runs in the browser; back-end runs on servers with databases. Learning all three is the fastest path from idea to product.", ["networks"], []],
  ["ai-basics", 3, "AI & machine learning", "Programs that learn patterns from data.", "Classical programming: rules + data → answers. Machine learning: data + answers → rules. A model trains on examples (cats vs dogs) and generalises to new ones. Neural networks stack simple weighted sums through nonlinear activations; training adjusts weights to reduce error. Garbage in, garbage out: data quality caps model quality.", ["complexity", "statistics-data"], []],
  ["statistics-data", 2, "Data analysis & statistics", "Summarise, visualise, and question data with code.", "Load a dataset, compute summaries (mean, median, spread), plot distributions, and hunt for outliers and bias. Correlation ≠ causation; sampling bias poisons conclusions; averages hide distributions. With code, a thousand rows take a second — the thinking is the hard part, and it is the same thinking as good science.", ["averages", "lists-arrays"], ["outlier-mean"]],
];

