export const CONCEPTS: Concept[] = [
  ...build("maths", MATHS),
  ...build("physics", PHYSICS),
  ...build("chemistry", CHEMISTRY),
  ...build("biology", BIOLOGY),
  ...build("computing", COMPUTING),
];

export const CONCEPTS_BY_ID: Record<string, Concept> = Object.fromEntries(
  CONCEPTS.map((c) => [c.id, c]),
);

export function getConcept(id: string): Concept | undefined {
  return CONCEPTS_BY_ID[id];
}

export function bySubject(subject: SubjectId): Concept[] {
  return CONCEPTS.filter((c) => c.subject === subject);
}

/** Depth-first ancestors (transitive prerequisites), nearest first. */
export function ancestorsOf(id: string): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  const walk = (cid: string) => {
    for (const p of CONCEPTS_BY_ID[cid]?.prereqs ?? []) {
      if (!seen.has(p)) {
        seen.add(p);
        out.push(p);
        walk(p);
      }
    }
  };
  walk(id);
  return out;
}

/** Direct + transitive dependents (concepts that need this one). */
export function descendantsOf(id: string): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  const walk = (cid: string) => {
    for (const c of CONCEPTS) {
      if (c.prereqs.includes(cid) && !seen.has(c.id)) {
        seen.add(c.id);
        out.push(c.id);
        walk(c.id);
      }
    }
  };
  walk(id);
  return out;
}

/** i18n KEYS, not English text — render with `t(STAGE_NAMES[stage])` so the
 *  stage band reads in the learner's language (keys `stage.0`…`stage.5` are
 *  authored for all 15 languages in lib/i18n.ts). */
export const STAGE_NAMES: Record<StageId, string> = {
  0: "stage.0",
  1: "stage.1",
  2: "stage.2",
  3: "stage.3",
  4: "stage.4",
  5: "stage.5",
};
